#!/usr/bin/env python3
"""Author and execute rich, saved-evidence notebooks without rerunning research."""
import json,os
from pathlib import Path
from run_notebooks import execute_notebook
R=Path(__file__).resolve().parents[1]
SETUP='''from pathlib import Path
import json,sys,math,statistics
r=Path.cwd()
if not (r/'artifacts/research').exists(): r=r.parent
sys.path.insert(0,str(r/'src'));sys.path.insert(0,str(r))
from scripts.review_visuals import table,figure,lines,bars
if 'display_bundle' not in globals():
 from IPython.display import display
 def display_bundle(data): display(data,raw=True)
b=json.loads((r/'artifacts/research/public_bundle.json').read_text());a=b['analysis']
p=json.loads((r/'artifacts/review/polish.json').read_text());chosen=b['selected']
print('Saved test:',b['as_of'],'Selected:',chosen,'Post-study review:',p['review_date'])'''
def md(text):return dict(cell_type='markdown',metadata={},source=text.splitlines(True))
def code(text):return dict(cell_type='code',metadata={},source=text.splitlines(True),execution_count=None,outputs=[])
def notebook(stem,title,question,parts,conclusion):
 cells=[md('# '+title+'\n\n'+question+'\n\nThis notebook reviews saved retrospective evidence. New descriptive calculations are post-study analysis, not new strategy selection or an untouched test.'),code(SETUP)]
 for h,explanation,c in parts:cells +=[md('## '+h+'\n\n'+explanation),code(c)]
 cells +=[md('## Interpretation\n\n'+conclusion)]
 for i,c in enumerate(cells):c['id']=stem[:2]+'-review-'+str(i)
 nb=dict(cells=cells,metadata={'kernelspec':{'name':'python3','display_name':'Python 3','language':'python'},'language_info':{'name':'python','version':'3.12'},'execution_method':'Sequential Python executor with captured HTML/SVG outputs; native Jupyter kernel not used'},nbformat=4,nbformat_minor=5)
 path=R/'notebooks'/(stem+'.ipynb');execute_notebook(nb,path,True);path.write_text(json.dumps(nb,indent=2)+'\n');print(stem,len(cells),'cells')
def main():
 os.chdir(R)
